def build_office(Guide):
    g=Guide('Srez_video_control.pdf','Видеоконтроль / Администратор',5)
    t=g.start('Проверить магазины за день')
    t=g.step(1,'Войдите как <b>«Администратор»</b>. Откройте <b>«Рабочий стол»</b>, проверьте дату справа и выберите <b>13:00, 17:00 или «Закрытие»</b>.',t)
    t=g.step(2,'Нажмите <b>«Требуют внимания»</b>. Чтобы разобраться, нажмите статус в строке нужного магазина.',t)
    t=g.shot('office-summary-v2',t,width=176)
    t=g.shot('office-table-v2',t+1,width=176)
    g.note('<b>Таблица и карточка показывают выбранное время.</b> «Нет отчёта» выделяет магазины без показателей. «Все магазины» возвращает полный список.',t+1,size=9.5)

    t=g.start('Замечание: что случилось и что делать')
    t=g.p('<b>Замечание - это вопрос к конкретному отчёту.</b> Например: не заполнены алкогольные единицы или сумма на 17:00 меньше суммы на 13:00. Это повод проверить данные.',t)+3
    t=g.p('<b>Где искать:</b> пункт <b>«Замечания»</b> слева или «Рабочий стол» → «Требуют внимания» → статус магазина. Причина показана в карточке над цифрами.',t)+3
    t=g.step(1,'Нажмите <b>«Задать вопрос магазину»</b>, напишите, что уточнить, затем <b>«Сохранить вопрос»</b>.',t)
    t=g.shot('office-question-fields-v2',t,width=176)
    t=g.step(2,'Продавец увидит вопрос в этом же дне и срезе. Его ответ появится ниже, в <b>«Замечания и пояснения»</b>. До выдачи продавцам доступов свяжитесь с магазином привычным способом.',t+2)
    t=g.step(3,'Если число неверное, продавец исправляет отчёт. Вы тоже можете нажать <b>«Исправить показатели»</b>, ввести точные значения и причину, затем <b>«Сохранить исправление»</b>.',t)
    t=g.step(4,'Если данные верны и ответ понятен: в блоке вопроса выберите <b>«Подтвердить исключение»</b>, напишите итог проверки и нажмите <b>«Сохранить решение»</b>.',t)
    g.note('<b>Нет отчёта</b> - показатели отсутствуют, срок неизвестен.<br/><b>Опаздывает</b> - известный срок уже прошёл, отчёта нет.<br/><b>Не полностью</b> - часть цифр отсутствует. Дополните отчёт; принятие пояснения само по себе пропуски не заполняет.<br/><b>Проверить</b> - есть открытый вопрос или автоматическое замечание.',t+2,size=9.5)

    t=g.start('Добавить или перевести сотрудника')
    t=g.p('<b>Сотрудники уже перенесены из реестра.</b> Не добавляйте всех заново. В «Управление» → «Сотрудники» сначала найдите ФИО через поиск.',t)+3
    t=g.step(1,'Если сотрудника нет: <b>«Добавить сотрудника»</b> → ФИО и должность → <b>«Сохранить»</b>. Карандаш в строке открывает существующую запись.',t)
    t=g.shot('office-employee-v2',t,width=116)
    t=g.step(2,'Назначьте его в магазин: <b>«Магазины» → карандаш → «Продавец 1» / «Продавец 2» → «Сохранить»</b>.',t+2)
    t=g.shot('office-team-row-v2',t,width=176)
    t=g.p('<b>Перевод:</b> уберите назначение в прежнем магазине и назначьте в новом.<br/><b>Увольнение:</b> уберите из магазина; в записи сотрудника снимите «Доступен для назначения в магазин». Старые отчёты сохранятся.<br/><b>Разовая подмена:</b> продавец вписывает ФИО прямо в отчёте.',t+2,size=10)+3
    g.note('<b>ФИО и логин - разные вещи.</b> Запись сотрудника не выдаёт доступ в сервис. Доступ к магазину выдаётся отдельно при запуске. Сейчас в рабочей базе активен только аккаунт офиса.',t,size=9.5)

    t=g.start('Изменить план или график')
    t=g.p('<b>План:</b> «Управление» → «Планы». Проверьте дату, найдите магазин и нажмите карандаш. Введите утверждённые значения и основание → <b>«Сохранить»</b>. Прежний план остаётся в истории.',t)+3
    t=g.shot('office-plan-fields-v2',t,width=135)
    t=g.p('<b>График:</b> «Магазины» → карандаш → «График и контроль сроков». Укажите реальные часы, дни недели и часовой пояс. Подтвердите график галочкой → <b>«Сохранить»</b>.',t+3)+3
    t=g.shot('office-schedule-v2',t,width=124)
    g.note('<b>Контроль включается со следующего рабочего дня.</b> Время на скриншоте учебное. Разовый выходной или сокращённый день: «Графики» → «Особый день». Сроки старых отчётов не меняются.',t+2,size=9.5)

    t=g.start('Уведомления и начало работы')
    t=g.p('<b>Telegram и MAX сообщают офису о проблеме</b> и дают ссылку на нужный отчёт. Вводить показатели и отвечать на вопросы нужно в сервисе.',t)+3
    t=g.p('Откройте <b>«Управление» → «Уведомления»</b>. Здесь видно, включён ли каждый канал, есть ли сообщения в очереди и когда была последняя отправка.',t)+3
    t=g.shot('office-notifications',t,width=176)
    t=g.sub('Какие сообщения будут приходить',t+4)
    t=g.p('Магазин не сдал отчёт к подтверждённому сроку; цифры требуют проверки; первый отчёт пришёл поздно; продавец ответил на вопрос офиса. В сообщении нажмите <b>«Открыть отчёт»</b>.',t)+4
    t=g.note('<b>Сейчас отправка выключена.</b> Для подключения специалисту нужны токены ботов, ID офисных чатов и внешний адрес сервиса. Старые пустые строки без известного срока не рассылаются как новые опоздания.',t,size=10)+5
    t=g.sub('Перед первым рабочим днём',t)
    t=g.step(1,'Подтвердите графики, проверьте сотрудников и планы.',t)
    t=g.step(2,'Получите у специалиста ссылку и доступы магазинов. Выдайте продавцам их инструкцию и согласуйте дату перехода.',t)
    t=g.step(3,'После перехода ведите новые отчёты и планы в сервисе. Старые Google-таблицы остаются архивом, синхронизации нет.',t)
    g.note('<b>Ежедневная работа офиса:</b> дата → время → «Требуют внимания» → проверить причины → связаться с магазином → проверить исправление или ответ.',t+2,size=10)
    g.finish()
